def plan_drop_route(adj: Mapping[str, Mapping[str, int]], origin: str, destination: str, drops: Sequence[str]) -> Optional[Tuple[int, List[str]]]:
    if len(drops) > 6:
        raise ValueError("too many drops")
    if len(set(drops)) != len(drops):
        raise ValueError("duplicate drops")
    for n in [origin, destination] + list(drops):
        if n not in adj:
            raise KeyError(f"node {n!r} not in adj")
    best_cost, best_path = float('inf'), None
    for p in permutations(drops):
        cost, path, node, possible = 0, [], origin, True
        for target in list(p) + [destination]:
            res = shortest_path(adj, node, target)
            if res is None:
                possible = False
                break
            c, pt = res
            cost += c
            path = path + pt if not path else path + pt[1:]
            node = target
        if possible and cost < best_cost:
            best_cost, best_path = cost, path
        elif possible and cost == best_cost:
            if best_path is None or path < best_path:
                best_path = path
    return (best_cost, best_path) if best_path is not None else None"}}}
