import heapq
from typing import Mapping, Optional, Tuple, List

def shortest_path(adj: Mapping[str, Mapping[str, int]], src: str, dst: str) -> Optional[Tuple[int, List[str]]]:
    if src not in adj or dst not in adj:
        raise KeyError("Source or destination depot not found in adjacency map")

    if src == dst:
        return (0, [src])

    # Priority Queue stores: (distance, num_legs, path)
    # heapq will handle the tie-breaking in the order of the tuple elements
    pq = [(0, 0, [src])]
    # visited stores the best (distance, num_legs, path) found so far to each node
    visited = {}

    while pq:
        dist, legs, path = heapq.heappop(pq)
        u = path[-1]

        if u == dst:
            return (dist, path)

        if u in visited and visited[u] <= (dist, legs, path):
            continue
        visited[u] = (dist, legs, path)

        for v, weight in adj.get(u, {}).items():
            new_dist = dist + weight
            new_legs = legs + 1
            new_path = path + [v]

            if v not in visited or (new_dist, new_legs, new_path) < visited[v]:
                heapq.heappush(pq, (new_dist, new_legs, new_path))

    return None
