from typing import Mapping, Dict, Optional

def hop_distances(adj: Mapping[str, Mapping[str, int]], source: str, max_hops: Optional[int] = None) -> Dict[str, int]:
    if source not in adj:
        raise KeyError(f"Source {source} not found in adjacency map")

    distances = {}
    queue = deque([(source, 0)])
    visited = {source}

    while queue:
        u, dist = queue.popleft()
        if max_hops is not None and dist > max_hops:
            continue

        distances[u] = dist

        if max_hops is not None and dist >= max_hops:
            continue

        # To satisfy the contract: depots with same hop count alphabetically by code
        # We sort neighbors by code before adding to queue to maintain order for same-distance nodes
        neighbors = sorted(adj.get(u, {}).keys())
        for v in neighbors:
            if v not in visited:
                visited.add(v)
                queue.append((v, dist + 1))

    # The BFS naturally visits in order of hop count.
    # However, we need to ensure the final dictionary is ordered by hop count, 
    # then alphabetically by code for those with the same hop count.
    # Since we processed in BFS order and sorted neighbors, the `distances` dict 
    # should already be in the correct insertion order.
    return distances
