from typing import Mapping, Sequence, Dict, Optional
from routekit.shortest_path import shortest_path

def assign_depots(adj: Mapping[str, Mapping[str, int]], depots: Sequence[str], customers: Sequence[str]) -> Dict[str, Optional[str]]:
    """
    Assign each customer location to its nearest depot by road distance.
    If multiple depots are at the same minimum distance, the one appearing first in the `depots` list is chosen.
    """
    assignments = {}
    for customer in customers:
        best_depot = None
        min_dist = float('inf')

        for depot in depots:
            # shortest_path raises KeyError if src or dst not in adj
            result = shortest_path(adj, depot, customer)
            if result is not None:
                dist, _ = result
                if dist < min_dist:
                    min_dist = dist
                    best_depot = depot

        assignments[customer] = best_depot
    return assignments
"
  }
 }
}
